-- Phase 2b: actions that change several rows at once (called by the app via RPC).
-- They run with the caller's permissions (SECURITY INVOKER), so RLS and the
-- guard triggers still apply; the role check only gives a clearer message.

-- ---------------------------------------------------------------------------
-- activate_contract: DRAFT -> ACTIVE (the plan of visits is generated by trigger)
-- ---------------------------------------------------------------------------
create function public.activate_contract(p_contract_id uuid)
returns public.contracts
language plpgsql
set search_path = ''
as $$
declare
  v_contract public.contracts;
begin
  if private.is_app_user() and not private.has_role('manager') then
    raise exception 'Only managers can activate contracts.' using errcode = '42501';
  end if;

  update public.contracts
     set status = 'ACTIVE'
   where id = p_contract_id and status = 'DRAFT'
  returning * into v_contract;

  if not found then
    raise exception 'Contract not found or not in DRAFT status.' using errcode = 'P0002';
  end if;
  return v_contract;
end;
$$;

-- ---------------------------------------------------------------------------
-- renew_contract: creates the next version (linked through previous_contract_id),
-- copies the units still in service, activates it and marks the old one RENEWED.
-- ---------------------------------------------------------------------------
create function public.renew_contract(
  p_contract_id        uuid,
  p_new_contract_number text default null,
  p_annual_value_eur   numeric default null,
  p_duration_months    integer default 12
)
returns public.contracts
language plpgsql
set search_path = ''
as $$
declare
  v_old public.contracts;
  v_new public.contracts;
  v_version integer;
begin
  if private.is_app_user() and not private.has_role('manager') then
    raise exception 'Only managers can renew contracts.' using errcode = '42501';
  end if;

  select * into v_old from public.contracts where id = p_contract_id for update;
  if not found then
    raise exception 'Contract not found.' using errcode = 'P0002';
  end if;
  if v_old.status <> 'ACTIVE' then
    raise exception 'Only ACTIVE contracts can be renewed (contract % is %).', v_old.contract_number, v_old.status
      using errcode = 'P0001';
  end if;
  if p_duration_months is null or p_duration_months not between 1 and 60 then
    raise exception 'Renewal duration must be between 1 and 60 months.' using errcode = 'P0001';
  end if;

  -- Version number = length of the renewal chain (VK-2025-014 -> VK-2025-014-R1 -> -R2 ...)
  with recursive chain as (
    select c.id, c.previous_contract_id from public.contracts c where c.id = v_old.id
    union all
    select c.id, c.previous_contract_id from public.contracts c join chain on c.id = chain.previous_contract_id
  )
  select count(*) into v_version from chain;

  insert into public.contracts (
    contract_number, customer_id, contract_type, status, start_date, end_date,
    notice_period_days, auto_renew, annual_value_eur, billing_frequency,
    sla_p1_hours, sla_p2_hours, sla_p3_hours, preventive_visits_per_year,
    notes, previous_contract_id)
  values (
    coalesce(nullif(btrim(p_new_contract_number), ''),
             regexp_replace(v_old.contract_number, '-R\d+$', '') || '-R' || v_version),
    v_old.customer_id, v_old.contract_type, 'DRAFT',
    v_old.end_date + 1,
    (v_old.end_date + 1 + make_interval(months => p_duration_months))::date - 1,
    v_old.notice_period_days, v_old.auto_renew, coalesce(p_annual_value_eur, v_old.annual_value_eur),
    v_old.billing_frequency, v_old.sla_p1_hours, v_old.sla_p2_hours, v_old.sla_p3_hours,
    v_old.preventive_visits_per_year, null, v_old.id)
  returning * into v_new;

  insert into public.contract_equipment (contract_id, equipment_id)
  select v_new.id, ce.equipment_id
  from public.contract_equipment ce
  join public.equipment e on e.id = ce.equipment_id
  where ce.contract_id = v_old.id and e.status = 'ACTIVE';

  update public.contracts set status = 'ACTIVE' where id = v_new.id returning * into v_new;
  update public.contracts set status = 'RENEWED' where id = v_old.id;

  return v_new;
end;
$$;

-- ---------------------------------------------------------------------------
-- terminate_contract: ACTIVE -> TERMINATED (later planned visits are cancelled by trigger)
-- ---------------------------------------------------------------------------
create function public.terminate_contract(p_contract_id uuid, p_terminated_on date, p_reason text)
returns public.contracts
language plpgsql
set search_path = ''
as $$
declare
  v_contract public.contracts;
begin
  if private.is_app_user() and not private.has_role('manager') then
    raise exception 'Only managers can terminate contracts.' using errcode = '42501';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'A termination reason is required.' using errcode = 'P0001';
  end if;

  update public.contracts
     set status = 'TERMINATED', terminated_on = p_terminated_on, termination_reason = btrim(p_reason)
   where id = p_contract_id and status = 'ACTIVE'
  returning * into v_contract;

  if not found then
    raise exception 'Contract not found or not ACTIVE.' using errcode = 'P0002';
  end if;
  return v_contract;
end;
$$;

-- ---------------------------------------------------------------------------
-- expire_contracts: daily job. Active contracts past their end date are renewed
-- automatically when auto_renew is set (as the contract says), otherwise EXPIRED.
-- ---------------------------------------------------------------------------
create function public.expire_contracts()
returns integer
language plpgsql
set search_path = ''
as $$
declare
  r record;
  v_count integer := 0;
begin
  if private.is_app_user() and not private.has_role('manager') then
    raise exception 'Only managers can run the contract expiry.' using errcode = '42501';
  end if;

  for r in
    select id, auto_renew from public.contracts
    where status = 'ACTIVE' and end_date < private.today()
    order by end_date
  loop
    if r.auto_renew then
      begin
        perform public.renew_contract(r.id);
      exception when others then
        -- e.g. all units decommissioned: nothing left to renew
        update public.contracts set status = 'EXPIRED' where id = r.id;
      end;
    else
      update public.contracts set status = 'EXPIRED' where id = r.id;
    end if;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

revoke execute on function public.activate_contract(uuid) from public, anon;
revoke execute on function public.renew_contract(uuid, text, numeric, integer) from public, anon;
revoke execute on function public.terminate_contract(uuid, date, text) from public, anon;
revoke execute on function public.expire_contracts() from public, anon;
grant execute on function public.activate_contract(uuid) to authenticated;
grant execute on function public.renew_contract(uuid, text, numeric, integer) to authenticated;
grant execute on function public.terminate_contract(uuid, date, text) to authenticated;
grant execute on function public.expire_contracts() to authenticated;

-- ---------------------------------------------------------------------------
-- Daily schedule (pg_cron, 01:15 UTC)
-- ---------------------------------------------------------------------------
create extension if not exists pg_cron with schema pg_catalog;
select cron.schedule('coverwatch-expire-contracts', '15 1 * * *', 'select public.expire_contracts()');
